script.lang:
ALTER TABLE amp_category_value_location
ADD COLUMN IF NOT EXISTS is_ggw BOOLEAN DEFAULT FALSE;

ALTER TABLE amp_category_value_location
ADD COLUMN IF NOT EXISTS is_ecowas BOOLEAN DEFAULT FALSE;

-- Update for GGW countries
UPDATE AMP_CATEGORY_VALUE_LOCATION
SET is_ggw = TRUE
WHERE UPPER(iso) IN (
    'BF', 'TD', 'DJ', 'ER', 'ET',
    'ML', 'MR', 'NE', 'NG', 'SN', 'SD'
);

-- Update for ECOWAS countries
UPDATE AMP_CATEGORY_VALUE_LOCATION
SET is_ecowas = TRUE
WHERE UPPER(iso) IN (
    'BJ', 'BF', 'CV', 'CI', 'GM',
    'GH', 'GN', 'GW', 'LR', 'ML',
    'NE', 'NG', 'SN', 'SL', 'TG'
);
